const makeQuestions = (items, idStart, bolim) => items.map(
  ([mavzu, qiyinlik, savol, answer, distractor1, distractor2, izoh], index) => {
    const togriJavob = index % 3
    const options = [distractor1, distractor2]
    options.splice(togriJavob, 0, answer)

    return {
      id: idStart + index,
      sinf: 6,
      bolim,
      mavzu,
      qiyinlik,
      savol,
      variantlar: options.map((option, optionIndex) => `${String.fromCharCode(65 + optionIndex)}) ${option}`),
      togriJavob,
      izoh
    }
  }
)

